function runtime() {
  const safeUrl=value=>{try{return ['http:','https:'].includes(new URL(value,location.href).protocol);}catch{return false;}};
  const all=selector=>[...document.querySelectorAll(selector)],one=selector=>document.querySelector(selector);
  const variables=(()=>{try{return JSON.parse(one('#forma-variable-data')?.textContent||'{}');}catch{return {};}})();
  const pageHistory=[];let currentPage=one('.forma-preview-stage')?.dataset.currentPage||one('[data-forma-page]')?.dataset.formaPage||'',overlayState=null;
  const dataKey=name=>'var'+String(name||'').replace(/[^a-z0-9_-]+/gi,'_');
  const esc=value=>globalThis.CSS?.escape?CSS.escape(value):String(value).replace(/"/g,'\\"');
  const parseValue=value=>{const raw=String(value??'').trim();if(raw==='true')return true;if(raw==='false')return false;if(raw!==''&&!Number.isNaN(Number(raw)))return Number(raw);return raw.replace(/^['"]|['"]$/g,'');};
  const compare=(left,op,right)=>op==='=='?left==right:op==='!='?left!=right:op==='>'?Number(left)>Number(right):op==='<'?Number(left)<Number(right):op==='>='?Number(left)>=Number(right):op==='<='?Number(left)<=Number(right):Boolean(left);
  const evaluateCondition=expression=>{const text=String(expression||'').trim();if(!text)return true;const negative=text.startsWith('!'),body=negative?text.slice(1).trim():text;const match=body.match(/^([A-Za-z_][\w.-]*)\s*(==|=|!=|>=|<=|>|<)\s*(.+)$/);let result;if(match){const left=variables[match[1]],op=match[2]==='='?'==':match[2],right=parseValue(match[3]);result=compare(left,op,right);}else result=Boolean(variables[body]);return negative?!result:result;};
  const applyConditions=()=>all('[data-forma-visible-if]').forEach(item=>{item.hidden=!evaluateCondition(item.dataset.formaVisibleIf);item.classList.toggle('is-condition-hidden',item.hidden);});
  const applyVariables=()=>{for(const [name,value] of Object.entries(variables)){document.body.dataset[dataKey(name)]=String(value);document.documentElement.style.setProperty('--'+String(name).replace(/[^a-z0-9_-]+/gi,'-'),String(value));all(`[data-forma-variable="${esc(name)}"]`).forEach(item=>{item.textContent=String(value);});}applyConditions();};
  const showFormaPage=(page,{transition='none',duration=0,record=true}={})=>{if(!page)return false;const targets=all('[data-forma-page]'),next=targets.find(item=>item.dataset.formaPage===page);if(!next)return false;const previous=targets.find(item=>item.dataset.formaPage===currentPage);if(record&&currentPage&&currentPage!==page)pageHistory.push(currentPage);for(const item of targets){const active=item===next;item.hidden=false;item.classList.toggle('is-active',active);if(active&&previous&&previous!==next&&duration>0&&transition!=='none'){const from=transition==='move-in'||transition==='push'?'translateX(24px)':'none';const animation=next.animate([{opacity:transition==='dissolve'?0:1,transform:from},{opacity:1,transform:'none'}],{duration:Math.min(3000,Math.max(0,duration)),easing:'cubic-bezier(.2,.8,.2,1)'});animation.finished.catch(()=>{});}else if(!active)item.hidden=true;}currentPage=page;all('[data-forma-page-target]').forEach(item=>item.classList.toggle('is-active',item.dataset.formaPageTarget===page));window.dispatchEvent(new CustomEvent('forma:preview-page',{detail:{page,transition,duration}}));return true;};
  const findTarget=value=>{if(!value)return null;try{return document.getElementById(value)||document.querySelector(value);}catch{return document.getElementById(value);}};
  const showMessage=message=>{let toast=one('[data-forma-preview-toast]');if(!toast){toast=document.createElement('div');toast.dataset.formaPreviewToast='';toast.setAttribute('role','status');toast.setAttribute('aria-live','polite');toast.style.cssText='position:fixed;left:50%;bottom:24px;z-index:2147483647;max-width:min(560px,calc(100vw - 32px));padding:12px 18px;border:1px solid #ffffff30;border-radius:12px;background:#17231f;color:#fff;font:500 14px/1.45 Inter,Arial,sans-serif;box-shadow:0 12px 38px #0003;transform:translateX(-50%);';document.body.append(toast);}toast.textContent=String(message||'Interaction');toast.hidden=false;clearTimeout(toast._formaTimer);toast._formaTimer=setTimeout(()=>{toast.hidden=true;},3200);};
  const closeOverlay=()=>{if(!overlayState)return false;const state=overlayState;overlayState=null;state.placeholder.replaceWith(state.target);state.target.style.cssText=state.style;state.target.hidden=state.hidden;state.backdrop.remove();return true;};
  const openOverlay=(value,{transition='dissolve',duration=250}={})=>{const target=findTarget(value);if(!target)return false;closeOverlay();const rect=target.getBoundingClientRect(),placeholder=target.ownerDocument.createElement('span'),backdrop=target.ownerDocument.createElement('div');placeholder.style.cssText=`display:inline-block;width:${Math.max(1,rect.width)}px;height:${Math.max(1,rect.height)}px;`;target.before(placeholder);const style=target.style.cssText,hidden=target.hidden;backdrop.dataset.formaOverlay='';backdrop.style.cssText='position:fixed;inset:0;z-index:2147483646;display:grid;place-items:center;padding:24px;background:rgba(13,18,15,.48);';const panel=target.ownerDocument.createElement('div');panel.style.cssText='max-width:min(100%,960px);max-height:calc(100vh - 48px);overflow:auto;box-shadow:0 18px 60px #0003;';panel.append(target);backdrop.append(panel);document.body.append(backdrop);target.style.position='relative';target.style.left='auto';target.style.top='auto';target.style.right='auto';target.style.bottom='auto';target.style.width=rect.width?`${rect.width}px`:target.style.width;target.style.maxWidth='100%';target.hidden=false;backdrop.addEventListener('click',event=>{if(event.target===backdrop)closeOverlay();});overlayState={target,placeholder,backdrop,style,hidden};if(transition!=='none'&&duration>0)panel.animate([{opacity:0,transform:transition==='move-in'||transition==='push'?'translateY(16px) scale(.98)':'scale(.98)'},{opacity:1,transform:'none'}],{duration:Math.min(3000,Math.max(0,duration)),easing:'cubic-bezier(.2,.8,.2,1)'}).finished.catch(()=>{});target.focus?.({preventScroll:true});return true;};
  const setVariable=(interaction,event)=>{const name=interaction.variable;if(!name)return;const next=interaction.value==='toggle'?!Boolean(variables[name]):interaction.value,source=event?.target?.closest?.('[data-forma-prototype]')||event?.currentTarget;variables[name]=next;source?.classList?.toggle('is-active',Boolean(next));source?.setAttribute?.('aria-pressed',String(Boolean(next)));applyVariables();window.dispatchEvent(new CustomEvent('forma:variables-change',{detail:{...variables}}));};
  const runAction=(action,event,element)=>{if(action.condition&&!evaluateCondition(action.condition))return true;const preventsDefault=['navigate-page','navigate','back','overlay','close-overlay','set-variable','submit-email'].includes(action.action);if(preventsDefault)event?.preventDefault();const execute=()=>{if(action.action==='navigate-page'||action.action==='navigate'){closeOverlay();showFormaPage(action.target,{transition:action.transition||'none',duration:action.duration||0});return;}if(action.action==='back'){if(!closeOverlay()){const previous=pageHistory.pop();if(previous)showFormaPage(previous,{record:false,transition:action.transition||'move-in',duration:action.duration||250});}return;}if(action.action==='overlay'){openOverlay(action.target,{transition:action.transition||'dissolve',duration:action.duration||250});return;}if(action.action==='close-overlay'){closeOverlay();return;}if(action.action==='set-variable'){setVariable(action,event);return;}const target=findTarget(action.target);if(action.action==='open-url'&&safeUrl(action.target))window.open(action.target,'_blank','noopener');if(action.action==='message')showMessage(action.target||'Interaction');if(action.action==='submit-email'){const input=target;if(!input?.value?.trim()){showMessage('Enter an email address to try the newsletter sign-up.');input?.focus?.();return false;}if(input.type==='email'&&input.checkValidity&&!input.checkValidity()){showMessage('Enter a valid email address to continue.');input.focus?.();return false;}input.value='';showMessage('Newsletter sign-up demo complete. No email was sent.');}if(action.action==='toggle'&&target)target.hidden=!target.hidden;if(action.action==='scroll'&&target)target.scrollIntoView({behavior:'smooth',block:'center'});return true;};return action.delay?new Promise(resolve=>setTimeout(()=>resolve(execute()),Math.min(10000,Number(action.delay)||0))):execute();};
  const runInteraction=(interaction,event,element)=>{if(interaction.trigger==='keydown'&&interaction.key&&event.key.toLowerCase()!==String(interaction.key).toLowerCase())return;const actions=Array.isArray(interaction.actions)?interaction.actions:(interaction.action?[interaction]:[]);let pending=null;for(const action of actions){if(pending)pending=pending.then(result=>result===false?false:runAction(action,event,element));else{const result=runAction(action,event,element);if(result===false)return false;if(result&&typeof result.then==='function')pending=result;}}return pending;};
  const prototypes=all('[data-forma-prototype]');prototypes.forEach(element=>{let saved;try{saved=JSON.parse(element.dataset.formaPrototype);}catch{return;}const interactions=(Array.isArray(saved)?saved:[saved]).filter(interaction=>interaction&&interaction.enabled!==false);if(!interactions.length)return;element.style.cursor='pointer';interactions.forEach(interaction=>{const trigger=interaction.trigger;if(trigger==='keydown')return;if(trigger==='dragstart'){element.draggable=true;element.addEventListener('dragstart',event=>{if(event.dataTransfer){event.dataTransfer.setData('text/plain',element.id||'forma-layer');event.dataTransfer.effectAllowed='move';}runInteraction(interaction,event,element);});}else if(trigger==='drop'){element.addEventListener('dragover',event=>event.preventDefault());element.addEventListener('drop',event=>{event.preventDefault();runInteraction(interaction,event,element);});}else element.addEventListener(['mouseenter','mouseleave','dblclick','mousedown','mouseup'].includes(trigger)?trigger:'click',event=>runInteraction(interaction,event,element));});});
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&closeOverlay()){event.preventDefault();return;}if(event.target?.matches?.('input,textarea,select,[contenteditable="true"]'))return;for(const element of prototypes){let saved;try{saved=JSON.parse(element.dataset.formaPrototype);}catch{continue;}for(const interaction of (Array.isArray(saved)?saved:[saved]))if(interaction.enabled!==false&&interaction.trigger==='keydown')runInteraction(interaction,event,element);}});
  document.addEventListener('click',event=>{const pageButton=event.target.closest?.('[data-forma-page-target]');if(pageButton){event.preventDefault();showFormaPage(pageButton.dataset.formaPageTarget);}});
  all('[data-page-target]').forEach(button=>button.addEventListener('click',event=>{event.preventDefault();const page=button.dataset.pageTarget;all('[data-page]').forEach(item=>item.classList.toggle('is-active',item.dataset.page===page));all('[data-page-target]').forEach(item=>item.classList.toggle('is-active',item.dataset.pageTarget===page));}));
  showFormaPage(currentPage,{record:false});
  applyVariables();
  one('#sidebar-collapse')?.addEventListener('click',()=>document.body.classList.toggle('sidebar-collapsed'));
  const toggleTheme=()=>{const dark=document.body.classList.toggle('dark-mode');for(const button of [one('#theme-toggle'),one('#settings-theme')].filter(Boolean)){button.classList.toggle('is-on',dark);button.setAttribute('aria-checked',String(dark));}};
  one('#theme-toggle')?.addEventListener('click',toggleTheme);one('#settings-theme')?.addEventListener('click',toggleTheme);
  all('.switch:not(#settings-theme)').forEach(button=>button.addEventListener('click',()=>{const on=button.classList.toggle('is-on');button.setAttribute('aria-checked',String(on));}));
}
export function buildPreviewRuntime(){return `<script>(${runtime.toString()})();<\/script>`;}
